import{_ as r,C as s,o,c as i,j as t,a as n,E as h,ah as p}from"./chunks/framework.Dmqp7bmQ.js";const y=JSON.parse('{"title":"Umpires and Python scripts","description":"","frontmatter":{},"headers":[],"relativePath":"umpires.md","filePath":"umpires.md"}'),d={name:"umpires.md"};function l(c,e,m,u,f,g){const a=s("Mermaid");return o(),i("div",null,[e[0]||(e[0]=t("h1",{id:"umpires-and-python-scripts",tabindex:"-1"},[n("Umpires and Python scripts "),t("a",{class:"header-anchor",href:"#umpires-and-python-scripts","aria-label":'Permalink to "Umpires and Python scripts"'},"​")],-1)),e[1]||(e[1]=t("p",null,"The White Force runs the game: the admin, who is the umpire, and the White Force's own roles. After version 1 (Phase 6), they can share the work through a room of their own and automate it with short Python scripts that run in the browser. Players and observers of the other forces see none of this.",-1)),h(a,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20White%5B%22White%20Force%20role%22%5D%0A%20%20%20%20%20%20%20%20WScript%5B%22Script%3A%20works%20out%20a%20new%20world%20state%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Umpires%5B%22Umpires%20room%22%5D%0A%20%20%20%20%20%20%20%20Proposal%5B%22Proposal%20card%3A%20state%20and%20summary%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Admin%5B%22The%20umpire's%20game%20view%22%5D%0A%20%20%20%20%20%20%20%20Load%5B%22Load%20into%20draft%3A%20change%20summary%20first%22%5D%0A%20%20%20%20%20%20%20%20AScript%5B%22Admin%20script%22%5D%0A%20%20%20%20%20%20%20%20Draft%5B(%22World-state%20draft%22)%5D%0A%20%20%20%20%20%20%20%20Publish%5B%22Publish%20world%20state%22%5D%0A%20%20%20%20end%0A%20%20%20%20MapRoom%5B(%22Map%20room%3A%20what%20every%20role%20sees%22)%5D%0A%20%20%20%20WScript%20--%3E%7Cpropose%7C%20Proposal%20--%3E%20Load%20--%3E%20Draft%0A%20%20%20%20AScript%20--%3E%7Cits%20changes%2C%20on%20top%20of%20the%20draft%7C%20Draft%0A%20%20%20%20Draft%20--%3E%20Publish%20--%3E%20MapRoom%0A%20%20%20%20AScript%20-.-%3E%7Conly%20if%20turned%20on%20for%20the%20script%7C%20MapRoom%0A"}),e[2]||(e[2]=p('<h2 id="the-umpires-room" tabindex="-1">The umpires room <a class="header-anchor" href="#the-umpires-room" aria-label="Permalink to &quot;The umpires room&quot;">​</a></h2><p>Every game has one umpires room, made with the map room when the game is first published. Like the map room, it cannot be deleted and its members are fixed: the admin and every White Force role. White Force roles that are not observers write in it; White Force observers can only read it. No other role sees it.</p><p>It is a chat room for the umpire team, and the place where White Force scripts send their proposed world states to the admin.</p><h2 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to &quot;Proposals&quot;">​</a></h2><p>A White Force script can work out a new world state, for example after an engagement, and propose it with a short summary of what it changes. The proposal arrives in the umpires room as a card. The admin&#39;s card has <strong>Load into draft…</strong>, which first shows the change summary against the published state, and warns if the admin&#39;s draft has unpublished edits that loading would replace. Once loaded, the proposal is the admin&#39;s draft, and the admin publishes it from the map room as usual. Everyone else sees the card only. Proposals may be posted during adjudication.</p><h2 id="scripts" tabindex="-1">Scripts <a class="header-anchor" href="#scripts" aria-label="Permalink to &quot;Scripts&quot;">​</a></h2><p>The admin, in the umpire&#39;s game view, and every White Force role that is not an observer have a <strong>Scripts</strong> tab in the strip at the bottom of the workspace. It can be dragged beside the rooms or popped out like any other panel.</p><ul><li><strong>Write and run.</strong> Create, rename, duplicate and delete scripts, edit the code, and run it. Output shows as it is printed, and an error shows Python&#39;s own report of where it went wrong. Stop ends a run at once, and every run has a time limit, 30 seconds unless the script sets another (at most 10 minutes), counted from when the script starts.</li><li><strong>Same rights as the role.</strong> A script reads the game as its role does: the turn, forces, roles, its rooms and their messages, the world state and objectives. It can send messages, plain or from a template, to rooms its role writes in, and it can do nothing the role cannot. During adjudication the White Force keeps posting, as people do.</li><li><strong>Reacting.</strong> A script can wait for new messages in a room, or for the turn or phase to change, and act on each one, for as long as it runs: for example, acknowledge every request in a room.</li><li><strong>The admin&#39;s draft.</strong> An admin script reads the world-state draft and changes it. Its changes land when the script finishes cleanly, on top of the draft as it is then, so edits the admin made by hand to other assets are kept; a stopped, timed-out or failed run leaves the draft as it was. The panel then says what the script changed and how the draft differs from what players see.</li><li><strong>Publishing without review.</strong> By default nothing a script does reaches the players&#39; map: the admin reviews the change summary in the map room and publishes. For each admin script, the admin may turn on <strong>Publish without review</strong>, after a confirmation that it will change the live map without review. Each clean run of that script that changes the draft then publishes it at once, with the same checks as a manual publish, and the panel keeps a record of each such publish: which script, which turn and what changed. A mistake is put right with an ordinary publish.</li><li><strong>Kept with the login.</strong> Scripts are stored on the server with the login, not in the browser, so they follow it to another device and to the next game, and everyone who shares a role&#39;s login shares its scripts. If two people save at once, the second is told and chooses whether to reload or keep their change.</li><li><strong>Files.</strong> Export saves all of a login&#39;s scripts as one file, and import adds scripts from such a file or from <code>.py</code> files. Importing never runs anything, and an imported script never publishes without review until the admin turns it on.</li></ul><p><a href="./scripting.html">Scripting for umpires</a> walks through a turn with scripts, with examples and good practice.</p><p>In a pull request&#39;s preview of the site, the app includes Python only when the pull request changes the Python parts; otherwise the Scripts panel says Python is not available in that build. The demo on the main site always has it.</p>',10))])}const b=r(d,[["render",l]]);export{y as __pageData,b as default};
